"""Review gallery UI regression with synthetic queue/media responses and a temporary authenticated QA session."""
import os,json,sqlite3
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
s=json.loads(Path(os.environ['ORBIT_QA_STATE_FILE']).read_text());base=os.environ['ORBIT_E2E_BASE_URL']
with sqlite3.connect(os.environ['ORBIT_QA_DB_PATH']) as db: project=db.execute("select id from short_video_accounts where project_type='short_video' order by id limit 1").fetchone()[0]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);c=b.new_context(viewport={'width':1440,'height':960});n,v=s['adminCookie'].split('=',1);c.add_cookies([{'name':n,'value':v,'url':base}]);page=c.new_page();page.on('dialog',lambda d:d.accept());errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 item={'code':'GALLERY-QA','title':'审核图文预览验收','contentType':'image_text','uploaderName':'测试上传人','versionNumber':1,'versionId':991,'queueItemId':991,'fileSize':100,'fileName':'image.png'}
 page.route('**/api/review-sessions',lambda r:r.fulfill(json={'session':{'id':991},'canProcess':True}))
 page.route('**/api/review-sessions/991',lambda r:r.fulfill(json={'items':[item],'canProcess':True}))
 page.route('**/api/contents/GALLERY-QA/versions',lambda r:r.fulfill(json={'versions':[{'current':True,'files':[{'fileUrl':f'/qa-image/{i}'} for i in range(3)]}]}))
 page.route('**/qa-image/*',lambda r:r.fulfill(content_type='image/svg+xml',body='<svg xmlns="http://www.w3.org/2000/svg" width="900" height="600"><rect width="900" height="600" fill="lightblue"/></svg>'))
 page.goto(base);page.locator(f'#project-tab-{project}').click();page.get_by_role('navigation',name='项目二级导航').get_by_role('button',name='审核中心',exact=True).click();images=page.locator('.content-image-enlarge');expect(images).to_have_count(3);images.nth(1).click();d=page.get_by_role('dialog',name='图文大图预览');expect(d.get_by_role('status')).to_have_text('2 / 3');expect(d.locator('img')).to_have_attribute('src','/qa-image/1');d.get_by_role('button',name='下一张 →',exact=True).click();expect(d.get_by_role('status')).to_have_text('3 / 3');expect(d.get_by_role('button',name='下一张 →',exact=True)).to_be_disabled();page.keyboard.press('ArrowLeft');expect(d.get_by_role('status')).to_have_text('2 / 3');page.keyboard.press('ArrowRight');expect(d.get_by_role('status')).to_have_text('3 / 3');d.get_by_role('button',name='← 上一张',exact=True).click();d.get_by_role('button',name='← 上一张',exact=True).click();expect(d.get_by_role('button',name='← 上一张',exact=True)).to_be_disabled();page.keyboard.press('Escape');expect(d).not_to_be_visible();expect(images.nth(1)).to_be_focused();images.first.click();expect(d.get_by_role('status')).to_have_text('1 / 3');page.set_viewport_size({'width':540,'height':900});expect(d.locator('img')).to_be_visible();assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+2');d.get_by_role('button',name='关闭弹窗',exact=True).click();expect(d).not_to_be_visible();assert not errors,errors;b.close();print(json.dumps({'checks':14,'pageErrors':errors,'syntheticReviewQueue':True}))
